<script setup lang="ts">
import {ref} from 'vue'
import {NButton,NInput,NModal} from 'naive-ui'
import {warehouse,versions,today,key,failure,type StockTransfer} from '../api/warehouse'
const props=defineProps<{item:StockTransfer;trusted:boolean}>(),emit=defineEmits<{changed:[];pending:[boolean]}>()
const show=ref(false),busy=ref(false),error=ref(''),date=ref(today()),basis=ref(''),observations=ref<Record<string,string>>({}),locked=ref(false)
let pending:Record<string,unknown>|null=null
async function save(){error.value='';try{if(!pending){const observed=props.item.lines.filter(l=>observations.value[l.id]!==undefined&&observations.value[l.id]!=='');if(observed.some(l=>!/^[0-9]+$/.test(observations.value[l.id]!)))throw new Error('实际数量须为非负整数，留空表示未观察');pending={...versions(props.item),effective_date:date.value,basis:basis.value,idempotency_key:key(),observations:observed.map(l=>({line_id:l.id,observed_quantity:observations.value[l.id],basis:basis.value}))};locked.value=true;emit('pending',true)}busy.value=true;await warehouse.action(`/stock-transfers/${props.item.id}/completion`,pending);show.value=false;pending=null;locked.value=false;emit('pending',false);emit('changed')}catch(e){error.value=failure(e);if([400,422].includes((e as {status?:number}).status||0)){locked.value=false;pending=null;emit('pending',false);error.value=(e as Error).message+'。请修正输入后提交。'}}finally{busy.value=false}}
</script>
<template><NButton @click="show=true">{{trusted?'确认完成':'申报已完成'}}</NButton><NModal v-model:show="show" preset="card" title="核对整条转移的实际完成情况" class="dialog"><p>{{item.source_location_name}} → {{item.destination_location_name}}。确认后按整条批准数量记账，实际观察差异单独记录。</p><ul><li v-for="l in item.lines" :key="l.id">{{l.sku_name}}：{{l.quantity}} {{l.unit}}<small v-if="item.source_kind==='physical'">{{item.source_location_name}} 扣减 {{l.quantity}} {{l.unit}}</small><small v-if="item.destination_kind==='physical'">{{item.destination_location_name}} 增加 {{l.quantity}} {{l.unit}}</small><label>实际观察数量（可留空）<NInput :disabled="locked" v-model:value="observations[l.id]" placeholder="非负整数；0 表示观察为零"/></label></li></ul><details><summary>批准范围</summary><pre>{{JSON.stringify(item.approval_snapshot,null,2)}}</pre></details><label>完成日期<NInput :disabled="locked" v-model:value="date"/></label><label>实际完成依据<NInput :disabled="locked" v-model:value="basis"/></label><p v-if="!trusted">申报提交后等待受信任用户审阅实际事实，审批通过才记录库存。</p><p class="error">{{error}}</p><NButton :loading="busy" @click="save">{{locked?'重试原请求':trusted?'确认整条转移已完成':'提交完成申报'}}</NButton></NModal></template>
